ROOT.scriptdef:
declare @MaxId int;
select @MaxId = max(FBN_Id) from cdn.FormBanNag
insert into CDN.FormBanNag(FBN_Id, FBN_Nazwa, FBN_Rozszerzenie, FBN_FormatDaty, FBN_Trim, FBN_SeparPol, FBN_SeparTys, FBN_ZnakDzies, FBN_OgrTekst, FBN_PodzWier, FBN_StronaKodowa, FBN_OddzielajPola, FBN_ZamianaOgrTekst, FBN_WielkieLitery, FBN_SeparTytulem, FBN_Opis, FBN_CDC, FBN_CDCAdres) values(@MaxId + 1,'Millennium Bank – WebService','','',1,'','','','','',0,0,'',0,'','', 1,'https://millenetlink.bankmillennium.pl/')
